import { EcsEvent } from "../lib/ecs-js/index.js";
import { normalizeGridPoint } from "../shared/math/point.js";

/**
 * Typed receipt for a deity-authored challenge being defeated and rewarded.
 */
export class DeityChallengeCompleted extends EcsEvent {
  constructor(payload = {}) {
    super();

    const challengeId = Number(payload.challengeId || 0) | 0;
    if (!(challengeId > 0)) throw new Error("DeityChallengeCompleted.challengeId must be positive");

    this.deityId = String(payload.deityId || "");
    this.playerId = Number(payload.playerId || 0) | 0;
    this.challengeId = challengeId;
    this.rewardId = Number(payload.rewardId || 0) | 0;
    this.rewardKind = String(payload.rewardKind || "");
    this.amount = Number(payload.amount || 0) | 0;
    this.at = normalizeGridPoint(payload.at);

    Object.freeze(this);
  }

  toLegacyPayload() {
    const out = {
      deityId: this.deityId,
      playerId: this.playerId,
      challengeId: this.challengeId,
      rewardId: this.rewardId,
      rewardKind: this.rewardKind,
      amount: this.amount,
    };
    if (this.at) out.at = { x: this.at.x | 0, y: this.at.y | 0 };
    return out;
  }
}

import { EcsEvent } from "../lib/ecs-js/index.js";

function normalizeRoom(room) {
  const rec = (room && typeof room === "object") ? room : {};
  return {
    x: Number(rec.x || 0) | 0,
    y: Number(rec.y || 0) | 0,
    w: Number(rec.w || 0) | 0,
    h: Number(rec.h || 0) | 0,
  };
}

/**
 * Typed receipt for a deity-authored challenge becoming active.
 */
export class DeityChallengeStarted extends EcsEvent {
  constructor(payload = {}) {
    super();

    const challengeId = Number(payload.challengeId || 0) | 0;
    if (!(challengeId > 0)) throw new Error("DeityChallengeStarted.challengeId must be positive");

    this.deityId = String(payload.deityId || "");
    this.playerId = Number(payload.playerId || 0) | 0;
    this.challengeId = challengeId;
    this.kind = String(payload.kind || "monster_ambush");
    this.reason = String(payload.reason || "");
    this.room = Object.freeze(normalizeRoom(payload.room));
    this.spawnedIds = Object.freeze(
      Array.isArray(payload.spawnedIds)
        ? payload.spawnedIds.map((id) => Number(id || 0) | 0).filter((id) => id > 0)
        : [],
    );

    Object.freeze(this);
  }

  toLegacyPayload() {
    return {
      deityId: this.deityId,
      playerId: this.playerId,
      challengeId: this.challengeId,
      kind: this.kind,
      reason: this.reason,
      room: { ...this.room },
      spawnedIds: this.spawnedIds.slice(),
    };
  }
}

